#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_ENTRIES 1024
#define ENTRY_SIZE 64
#define HEADER_SIZE 16

typedef struct {
    char name[32];
    uint32_t permissions;
    int32_t data_offset;
    int32_t data_length;
} CatalogEntry;

typedef struct {
    int32_t num_entries;
    int32_t total_size;
    char signature[8];
} CatalogHeader;

typedef struct {
    CatalogHeader header;
    CatalogEntry entries[MAX_ENTRIES];
    char data_pool[65536];
    int pool_used;
} Catalog;

static Catalog g_catalog;

/* Security: Validate that entry index is within bounds */
static int validate_entry_index(int32_t index) {
    if (index < 0 || index >= g_catalog.header.num_entries) {
        return -1;
    }
    return 0;
}

/* Security: Validate data region doesn't exceed pool */
static int validate_data_region(int32_t offset, int32_t length) {
    /* Ensure no negative values */
    if (offset < 0 || length < 0) {
        return -1;
    }
    /* Ensure the total accessed region fits within data_pool */
    /* Use 64-bit arithmetic to prevent overflow */
    int64_t end = (int64_t)offset + (int64_t)length;
    if (end > (int64_t)sizeof(g_catalog.data_pool)) {
        return -1;
    }
    return 0;
}

/* Initialize catalog from untrusted network data */
int catalog_init(const char *raw_data, size_t raw_len) {
    if (raw_len < sizeof(CatalogHeader)) {
        return -1;
    }

    memset(&g_catalog, 0, sizeof(Catalog));
    memcpy(&g_catalog.header, raw_data, sizeof(CatalogHeader));

    /* Security: Verify signature */
    if (memcmp(g_catalog.header.signature, "CATV2\x00\x00\x00", 8) != 0) {
        return -1;
    }

    /* Security: Validate entry count */
    if (g_catalog.header.num_entries < 0 || 
        g_catalog.header.num_entries > MAX_ENTRIES) {
        return -1;
    }

    /* Security: Validate total_size against actual data */
    if (g_catalog.header.total_size < 0) {
        return -1;
    }

    size_t expected_min = sizeof(CatalogHeader) + 
        (size_t)g_catalog.header.num_entries * sizeof(CatalogEntry);
    if (raw_len < expected_min) {
        return -1;
    }

    /* Copy entries */
    memcpy(g_catalog.entries, 
           raw_data + sizeof(CatalogHeader),
           (size_t)g_catalog.header.num_entries * sizeof(CatalogEntry));

    /* Copy data pool */
    size_t pool_data_start = expected_min;
    size_t pool_data_len = raw_len - pool_data_start;
    if (pool_data_len > sizeof(g_catalog.data_pool)) {
        pool_data_len = sizeof(g_catalog.data_pool);
    }
    memcpy(g_catalog.data_pool, raw_data + pool_data_start, pool_data_len);
    g_catalog.pool_used = (int)pool_data_len;

    return 0;
}

/* Read entry data into caller-supplied buffer */
int catalog_read_entry(int32_t index, char *out_buf, size_t out_buf_size) {
    if (validate_entry_index(index) != 0) {
        return -1;
    }

    CatalogEntry *entry = &g_catalog.entries[index];

    /* Security: Validate the data region for this entry */
    if (validate_data_region(entry->data_offset, entry->data_length) != 0) {
        return -1;
    }

    /* Security: Don't overflow output buffer */
    size_t copy_len = (size_t)entry->data_length;
    if (copy_len > out_buf_size) {
        copy_len = out_buf_size;
    }

    memcpy(out_buf, g_catalog.data_pool + entry->data_offset, copy_len);
    return (int)copy_len;
}

/* Update entry data - used by admin operations */
int catalog_write_entry(int32_t index, const char *new_data, int32_t new_length) {
    if (validate_entry_index(index) != 0) {
        return -1;
    }

    /* Security: Validate new_length */
    if (new_length < 0 || new_length > 4096) {
        return -1;
    }

    CatalogEntry *entry = &g_catalog.entries[index];

    /* Security: Validate write target region */
    if (validate_data_region(entry->data_offset, new_length) != 0) {
        return -1;
    }

    memcpy(g_catalog.data_pool + entry->data_offset, new_data, (size_t)new_length);
    entry->data_length = new_length;
    return 0;
}

/* Batch copy: copy data from one entry region to another */
int catalog_batch_transfer(int32_t src_index, int32_t dst_index, int32_t extra_padding) {
    if (validate_entry_index(src_index) != 0 || 
        validate_entry_index(dst_index) != 0) {
        return -1;
    }

    CatalogEntry *src = &g_catalog.entries[src_index];
    CatalogEntry *dst = &g_catalog.entries[dst_index];

    /* Security: Validate source region */
    if (validate_data_region(src->data_offset, src->data_length) != 0) {
        return -1;
    }

    /* Security: Reject negative padding */
    if (extra_padding < 0) {
        return -1;
    }

    /* Calculate total write size with overflow check */
    int64_t total_write_64 = (int64_t)src->data_length + (int64_t)extra_padding;
    if (total_write_64 > INT32_MAX || total_write_64 < 0) {
        return -1;
    }
    int32_t total_write = (int32_t)total_write_64;

    /* Security: Validate destination can hold the data */
    if (validate_data_region(dst->data_offset, total_write) != 0) {
        return -1;
    }

    memcpy(g_catalog.data_pool + dst->data_offset,
           g_catalog.data_pool + src->data_offset,
           (size_t)total_write);

    dst->data_length = total_write;
    return 0;
}
